50	// The prose half: an instruction that says to mark an issue for the queue and
51	// leaves the label to the reader is what produced those invented labels.
52	const judgeProse = (files) => {
53	  const rule = declaredCheck(PACK, 'queue-mark-named-literally');
54	  const root = makeRepo({ changed: files });
55	  try { return runRule(rule, buildContext({ root, mode: 'all' })).map((f) => f.what); }
56	  finally { cleanup(root); }
57	};
