59	test('an instruction that files queue work names the mark literally', () => {
60	  assert.deepEqual(judgeProse({
61	    'packs/acme-pack/skills/acme-skill/SKILL.md': 'an ordinary issue, marked for the queue, carrying its own brief.\n',
62	    'packs/acme-pack/tasks/acme-task/task.md': 'land the lesson as prose and open a tagged conformance-backlog issue.\n',
63	  }), [
64	    'an instruction to mark an issue for the queue that names no label: "marked for the queue"',
65	    'a backlog issue asked for by a tag nothing defines: "tagged conformance-backlog issue"',
66	  ]);
67	  // Naming the mark on the line is what clears it, whichever way the sentence
68	  // reaches it — in a local pack's prose too, the tree no converge rewrites.
69	  assert.deepEqual(judgeProse({
70	    '.claudinite/local/packs/acme-pack/RULES.md': 'an ordinary issue, marked for the queue with `task:origin:ad-hoc`, carrying its brief.\n',
71	    'packs/acme-pack/RULES.md': 'open a tagged backlog issue, marked `task:origin:ad-hoc`, for the conversion.\n',
72	  }), []);
73	  // Prose that neither files nor marks anything: the words the rule watches for
74	  // are what it fires on, and a README is not an instruction surface.
75	  assert.deepEqual(judgeProse({
76	    'packs/acme-pack/README.md': 'an ordinary issue, marked for the queue.\n',
77	    'packs/acme-pack/RULES.md': 'the queue adopts the issue and gives it a status.\n',
78	  }), []);
